"""
CORAL v0.1.1 - build hook.  Writes coral_pkg.vhd next to this file (pure python, system python3).
Heirloom from the video clips; still WIN_20230905_00_44_28 t0.5 (clip frame 15 at 0.5 s).

The patch (.heirloom_work/rb_coral/notes.md), in virtual 1080-line coordinates, F in bands (Q8 in the RTL):
  F   = g cos(2 pi (y - yr(t)) / 2215)            a free-running vertical sine rolling DOWN 248 lines/s (8.9 s)
      - A (1 - cos(pi |X| / 1000)) / 2             a mirrored horizontal cosine: low at the edges (the arc fans)
      - D max(0, 1 - |X|/420 - |Y|/ry)              a diamond key (the eye), ry = 250 above / 420 below y 430
  w   = 1 - 1.3 dist(F*rings - ph, integer)         a triangle wavefolder into the colouriser (red at every band)
  w   = max(w, floor(cos))                           the ground rises from cyan to violet where the sine is high
  w   = 1 where F > fz                               the outer zone (travelling red)
  w   = 1 inside the still's three solid shapes      the triangle, the hooked "v" bar and the hexagon bulb, a per-row
                                                     table measured on the still, translated with the rolling sine

ROMs written:
  C_CO_PAL   512 x 32  palette (Coral 0..255, Lagoon 256..511) by w: Y10 << 20 | U10 << 10 | V10 (hardware convention)
  C_CO_HT    1024 x 16 round(256 (1 - cos(pi min(X,1000)/1000)) / 2), X = |x - 960| virtual px (0..1023)
  C_CO_SIN   512 x 16  quarter sine: round(32767 sin(pi/2 (i + 0.5) / 512))
  C_CO_SHP   512 x 32  solid shapes per pair of shape rows yr = 384 + 2i: Nc/8 (5) | Wc/2 (9) | Hi/2 (9) | Ho/2 (9),
                       central run [Nc, Wc) and outer run [Hi, Ho) in virtual px from the centre (measured on the still)
  C_CO_EXP2  256 x 16  round(32768 * 2^(i/256))
"""
import math
import os

HERE = os.path.dirname(os.path.abspath(__file__))

# solid shapes, one 32-bit word per pair of shape rows (generated by .heirloom_work/rb_coral/shapetab.py)
SHP_HEX = ""

# palette anchors (RGB) along w = 0 .. 1, measured on the still (k-means + the band profiles)
CORAL = [(0, 170, 240), (72, 130, 242), (140, 110, 225), (205, 95, 145), (255, 45, 0)]
LAGOON = [(10, 40, 70), (20, 120, 110), (90, 200, 150), (230, 225, 120), (255, 250, 210)]


def rgb_to_hw10(r, g, b):
    y = 0.299 * r / 255 + 0.587 * g / 255 + 0.114 * b / 255
    cb = (b / 255 - y) / 1.772
    cr = (r / 255 - y) / 1.402
    return (int(round(64 + y * 876)), int(round(512 + cr * 896)), int(round(512 + cb * 896)))


def pal(anchors):
    out = []
    for i in range(256):
        w = i / 255 * 4
        k = min(int(w), 3)
        f = w - k
        c = [anchors[k][j] * (1 - f) + anchors[k + 1][j] * f for j in range(3)]
        y, u, v = rgb_to_hw10(*c)
        y = min(940, int(round(64 + (y - 64) * 16 / 13)))     # luma pre-scaled 16/13 (the output stage takes 13/16)
        y = min(y, 64 + int(round((768 - 64) * 16 / 13)))     # drawn luma cap ~768 after the scale
        u = max(0, min(1023, u))
        v = max(0, min(1023, v))
        out.append((y << 20) | (u << 10) | v)
    return out


def tables():
    p = pal(CORAL) + pal(LAGOON)
    ht = [int(round(256 * (1 - math.cos(math.pi * min(x, 1000) / 1000)) / 2)) for x in range(1024)]
    sn = [int(round(32767 * math.sin(math.pi / 2 * (i + 0.5) / 512))) for i in range(512)]
    ex = [min(65535, int(round(32768 * 2 ** (i / 256.0)))) for i in range(256)]
    shp = [int(SHP_HEX[i:i + 8], 16) for i in range(0, len(SHP_HEX), 8)]
    return p, ht, sn, ex, shp


def rom(lines, name, typ, n, width, vals, hexw):
    lines.append("    type %s is array (0 to %d) of std_logic_vector(%d downto 0);" % (typ, n - 1, width - 1))
    lines.append("    constant %s : %s := (" % (name, typ))
    for i in range(0, n, 8):
        row = ", ".join('x"%0*x"' % (hexw, vals[j]) for j in range(i, i + 8))
        lines.append("        " + row + ("," if i + 8 < n else ""))
    lines.append("    );")


def main():
    p, ht, sn, ex, shp = tables()
    L = ["-- Generated by coral.py: do not edit.  Palettes, H cosine table, quarter sine, exp2, solid shapes.",
         "library ieee;", "use ieee.std_logic_1164.all;", "use ieee.numeric_std.all;", "",
         "package coral_pkg is"]
    rom(L, "C_CO_PAL", "t_co_pal", 512, 32, p, 8)
    rom(L, "C_CO_HT", "t_co_ht", 1024, 16, ht, 4)
    rom(L, "C_CO_SIN", "t_co_sin", 512, 16, sn, 4)
    rom(L, "C_CO_EXP2", "t_co_exp2", 256, 16, ex, 4)
    rom(L, "C_CO_SHP", "t_co_shp", 512, 32, shp, 8)
    L.append("end package coral_pkg;")
    with open(os.path.join(HERE, "coral_pkg.vhd"), "w") as f:
        f.write("\n".join(L) + "\n")
    print("coral_pkg.vhd written (PAL 512 x 32, HT 1024 x 16, SIN 512 x 16, EXP2 256 x 16, SHP 512 x 32)")


if __name__ == "__main__":
    main()
